<span class="line"><span class="s_1i4ay4">    @invalid</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">(email) =&gt; console.warn(&#39;rejected&#39;, email)</span><span class="s_w1p9wo">&quot;</span></span>
